SELECT conrelid::regclass AS tbl, conname FROM pg_constraint WHERE contype = 'u' AND conrelid IN ('universities'::regclass, 'neighborhoods'::regclass, 'cities'::regclass, 'countries'::regclass, 'roles'::regclass, 'amenities'::regclass, 'utilities'::regclass, 'hygiene_categories'::regclass, 'property_types'::regclass, 'discussion_categories'::regclass, 'high_schools'::regclass, 'utility_types'::regclass);
